WITH unpacked AS (SELECT id, created_at, coupon_codes, items, ARRAY_MAX(TRANSFORM(items, i -> i.price)) AS max_item_price, ship_to.country AS ship_country, attributes['utm_source'] AS utm_source, AGGREGATE(items, CAST(0 AS DOUBLE), (acc, i) -> acc + i.qty * i.price, acc -> ROUND(acc, 2)) AS items_total FROM carts) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, APPROX_PERCENTILE(items_total, ARRAY(0.25, 0.5, 0.75)) AS items_total_quartiles, COUNT(DISTINCT ship_country) AS distinct_ship_countries, MIN(created_at) AS started_at FROM unpacked GROUP BY DATE_TRUNC('DAY', created_at) HAVING COUNT(DISTINCT ship_country) >= 1 ORDER BY activity_day DESC;
